            counts = {}
            # Read K_i face values and count frequencies
            for _ in range(K):
                val = int(next(iterator))
                counts[val] = counts.get(val, 0) + 1
            dice_maps.append(counts)
            dice_K.append(K)
        except StopIteration:
            break

    max_prob = 0.0

    # Iterate over all unique pairs of dice (i, j) with i < j
    for i in range(N):
        map_i = dice_maps[i]
        K_i = dice_K[i]

        for j in range(i + 1, N):
            map_j = dice_maps[j]
            K_j = dice_K[j]

            # Calculate the sum of products of counts for common values
            # P(X_i = v and X_j = v) = (count(i, v) / K_i) * (count(j, v) / K_j)
            # Sum over v: (1 / (K_i * K_j)) * sum(count(i, v) * count(j, v))

            # Optimization: Iterate over the smaller dictionary to minimize lookups
            if len(map_i) < len(map_j):
                current_sum = 0
                for val, count_i in map_i.items():
                    if val in map_j:
                        current_sum += count_i * map_j[val]
            else:
                current_sum = 0
                for val, count_j in map_j.items():
                    if val in map_i:
                        current_sum += count_j * map_i[val]

            # Calculate probability
            prob = current_sum / (K_i * K_j)
            if prob > max_prob:
                max_prob = prob

    # Print the result with sufficient precision
    print(f"{max_prob:.15f}")

