        # Define the range for this layer
        r_top = l - 1
        r_bottom = N - l
        c_left = l - 1
        c_right = N - l

        # We process the perimeter of the square defined by [r_top, r_bottom] x [c_left, c_right]
        # Since m is constant for this layer, we can optimize the inner loop

        if m == 0:
            # No rotation (360 degrees)
