sys.setrecursionlimit(20000)

def solve():
    # Read all input from stdin
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        N = int(next(iterator))
        Q = int(next(iterator))
    except StopIteration:
        return

    instructions = []
    for _ in range(Q):
        H = next(iterator)
        T = int(next(iterator))
        instructions.append((H, T - 1)) # 0-based index

    INF = 10**18
    dp = [INF] * N

    # Helper for distance
    # Inlined for performance and memory efficiency
    # def get_dist(a, b):
    #     d = abs(a - b)
    #     return d if d <= N // 2 else N - d

    # Initial state: L=0, R=1
    # Process first instruction
    if Q == 0:
        print(0)
        return

    H0, T0 = instructions[0]

    if H0 == 'L':
        # L moves 0 -> T0, R moves 1 -> p'
        # Cost: dist(0, T0) + dist(1, p')
        # Forbidden p': 0 (L's start), T0 (L's end)
        d0_T0 = abs(0 - T0)
        if d0_T0 > N // 2:
            d0_T0 = N - d0_T0

        for p in range(N):
            if p == 0 or p == T0:
                dp[p] = INF
            else:
                d1_p = abs(1 - p)
                if d1_p > N // 2:
                    d1_p = N - d1_p
                dp[p] = d0_T0 + d1_p
    else:
        # R moves 1 -> T0, L moves 0 -> p'
        # Cost: dist(1, T0) + dist(0, p')
        # Forbidden p': 1 (R's start), T0 (R's end)
        d1_T0 = abs(1 - T0)
        if d1_T0 > N // 2:
            d1_T0 = N - d1_T0

        for p in range(N):
            if p == 1 or p == T0:
                dp[p] = INF
            else:
                d0_p = abs(0 - p)
                if d0_p > N // 2:
                    d0_p = N - d0_p
                dp[p] = d1_T0 + d0_p

    # Process remaining instructions
    for k in range(1, Q):
        H_prev, T_prev = instructions[k-1]
        H_curr, T_curr = instructions[k]

        new_dp = [INF] * N

        if H_curr == H_prev:
            # Case 1: Same hand moves
            # H moves T_prev -> T_curr
            # O moves p -> p'
            # Cost: dist(T_prev, T_curr) + dist(p, p')
            # Forbidden p': T_prev (O's start), T_curr (H's end)

            d_Tprev_Tcurr = abs(T_prev - T_curr)
            if d_Tprev_Tcurr > N // 2:
                d_Tprev_Tcurr = N - d_Tprev_Tcurr

            # Distance transform on dp
            # B = dp + dp
            B = dp + dp
            # Forward pass
            for i in range(1, 2 * N):
                v = B[i-1] + 1
                if v < B[i]:
                    B[i] = v
            # Backward pass
            for i in range(2 * N - 2, -1, -1):
                v = B[i+1] + 1
                if v < B[i]:
                    B[i] = v

            forbidden = {T_prev, T_curr}

            for p_prime in range(N):
                if p_prime in forbidden:
                    new_dp[p_prime] = INF
                else:
                    val = B[p_prime]
                    if B[p_prime + N] < val:
                        val = B[p_prime + N]
                    new_dp[p_prime] = d_Tprev_Tcurr + val
        else:
            # Case 2: Different hand moves
            # H moves p -> T_curr
            # O moves T_prev -> p'
            # Cost: dist(p, T_curr) + dist(T_prev, p')
            # Forbidden p': T_curr (H's end)
            # Also p' != p (O cannot move to H's start)

            # Compute cost_p[p] = dp[p] + dist(p, T_curr)
            # Find min1, p1, min2, p2

            min1 = INF
            p1 = -1
            min2 = INF
            p2 = -1

            for p in range(N):
                if dp[p] == INF:
                    continue
                d_p_Tcurr = abs(p - T_curr)
                if d_p_Tcurr > N // 2:
                    d_p_Tcurr = N - d_p_Tcurr
                c = dp[p] + d_p_Tcurr
                if c < min1:
                    min2 = min1
                    p2 = p1
                    min1 = c
                    p1 = p
                elif c < min2:
                    min2 = c
                    p2 = p

            for p_prime in range(N):
                if p_prime == T_curr:
                    new_dp[p_prime] = INF
                else:
                    if p_prime != p1:
                        term = min1
                    else:
                        term = min2

                    if term == INF:
                        new_dp[p_prime] = INF
                    else:
                        d_Tprev_pprime = abs(T_prev - p_prime)
                        if d_Tprev_pprime > N // 2:
                            d_Tprev_pprime = N - d_Tprev_pprime
                        new_dp[p_prime] = term + d_Tprev_pprime

        dp = new_dp

    # Result is min(dp)
    print(min(dp))

if __name__ == '__main__':
    solve()
