from typing import List

class Solution:
    def countValidSelections(self, nums: List[int]) -> int:
        n = len(nums)
        count = 0

        # Identify all starting positions where nums[i] == 0
        starts = [i for i, x in enumerate(nums) if x == 0]

        for start in starts:
            for direction in [-1, 1]:
                if self.simulate(nums, start, direction):
                    count += 1
        return count

    def simulate(self, nums, start, direction):
        # We need to work on a copy of the array
        arr = nums[:]
        curr = start
        dir = direction
        non_zero_count = sum(1 for x in arr if x > 0)

        # If initially all zeros, it's valid (we just move out)
        if non_zero_count == 0:
            return True

        while 0 <= curr < len(arr):
            if arr[curr] == 0:
                curr += dir
            else:
                arr[curr] -= 1
                if arr[curr] == 0:
                    non_zero_count -= 1
                    if non_zero_count == 0:
                        return True
                dir = -dir
                curr += dir

        return False

if __name__ == "__main__":
