from typing import List

class Solution:
    def minArraySum(self, nums: List[int], k: int, op1: int, op2: int) -> int:
        # dp[i][j] stores the maximum reduction possible using at most i Op1s and j Op2s
        # Initialize with -1 to represent unreachable states
        dp = [[-1] * (op2 + 1) for _ in range(op1 + 1)]
        dp[0][0] = 0

        for x in nums:
            # Iterate backwards to avoid using the same item multiple times for the same state
            for i in range(op1, -1, -1):
                for j in range(op2, -1, -1):
                    if dp[i][j] == -1:
                        continue

                    current_reduction = dp[i][j]

                    # Option 1: Apply Operation 1
                    if i + 1 <= op1:
                        red1 = x // 2
                        if dp[i+1][j] < current_reduction + red1:
                            dp[i+1][j] = current_reduction + red1

                    # Option 2: Apply Operation 2
                    if j + 1 <= op2 and x >= k:
                        red2 = k
                        if dp[i][j+1] < current_reduction + red2:
                            dp[i][j+1] = current_reduction + red2

                    # Option 3: Apply Both Operations
                    if i + 1 <= op1 and j + 1 <= op2 and x >= k:
                        # Determine the best reduction for both operations
                        # If ceil(x/2) >= k, we can do Op1 then Op2
                        # Reduction = floor(x/2) + k
                        # Else, we must do Op2 then Op1
                        # Reduction = x - ceil((x-k)/2)

                        if (x + 1) // 2 >= k:
                            redBoth = (x // 2) + k
                        else:
                            redBoth = x - ((x - k + 1) // 2)

                        if dp[i+1][j+1] < current_reduction + redBoth:
                            dp[i+1][j+1] = current_reduction + redBoth

        max_reduction = 0
        for i in range(op1 + 1):
            for j in range(op2 + 1):
                if dp[i][j] > max_reduction:
                    max_reduction = dp[i][j]

        return sum(nums) - max_reduction

