from typing import List

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        n = len(nums)
        parent = list(range(n))
        rank = [0] * n

        def find(i):
            path = []
            while i != parent[i]:
                path.append(i)
                i = parent[i]
            for node in path:
                parent[node] = i
            return i

        def union(i, j):
            root_i = find(i)
            root_j = find(j)
            if root_i != root_j:
                if rank[root_i] < rank[root_j]:
                    parent[root_i] = root_j
                elif rank[root_i] > rank[root_j]:
                    parent[root_j] = root_i
                else:
                    parent[root_j] = root_i
                    rank[root_i] += 1
                return True
            return False

        # Map value to index for values <= threshold
        # Values > threshold are not mapped, they remain isolated
        val_to_idx = [-1] * (threshold + 1)
        for i, x in enumerate(nums):
            if x <= threshold:
                val_to_idx[x] = i

        # first_divisor[m] stores the first number from nums that divides m
        first_divisor = [0] * (threshold + 1)

        # Iterate over all possible values x in nums that are <= threshold
        # We iterate x from 1 to threshold and check if it exists in nums
        for x in range(1, threshold + 1):
            if val_to_idx[x] == -1:
                continue

            # x is in nums. Iterate multiples of x up to threshold.
            # For each multiple m, x divides m.
            # If m has another divisor y in nums, x and y are connected via m.
            # We union x with the first divisor found for m.
            for m in range(x, threshold + 1, x):
                if first_divisor[m] == 0:
                    first_divisor[m] = x
                else:
                    # Union x with first_divisor[m]
                    idx_x = val_to_idx[x]
                    idx_first = val_to_idx[first_divisor[m]]
                    union(idx_x, idx_first)

        # Count components
        roots = set()
        for i in range(n):
            roots.add(find(i))
        return len(roots)

if __name__ == "__main__":
