import sys
from typing import List
import ast

class Solution:
    def buttonWithLongestTime(self, events: List[List[int]]) -> int:
        max_time = -1
        best_index = -1
        prev_time = 0

        for index, time in events:
            current_time = time - prev_time
            prev_time = time

            if current_time > max_time:
                max_time = current_time
                best_index = index
            elif current_time == max_time:
                if index < best_index:
                    best_index = index

        return best_index

